async function readinessCall(action,data={}){const r=await fetch('/api/readiness/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
const beforeReadiness=render;render=function(){if(location.hash==='#readiness-check'){document.getElementById('app').innerHTML=integratedShell('readiness-check',heading('Find your starting point','Ten-question advisory self-check · Draft')+'<section class="card prose"><p>No admission decision, credit award or enrollment. Your answers are not stored.</p><div id="readiness-content" aria-live="polite">Loading questions…</div><div id="readiness-result" role="status"></div></section>',model.role);bind();readinessCall('questions').then(d=>{const n=document.getElementById('readiness-content');if(n)n.innerHTML=`<form id="readiness-form"><label>Learning goal<select name="goal"><option value="agents">Build AI agents</option><option value="data">Data and machine learning</option></select></label>${d.questions.map(q=>`<fieldset><legend>${q.id}. ${esc(q.prompt)}</legend>${q.options.map((o,i)=>`<label style="display:block"><input type="radio" name="q${q.id}" value="${i}" required> ${esc(o)}</label>`).join('')}</fieldset>`).join('')}<button class="button">Show recommendations</button></form>`;}).catch(e=>{const n=document.getElementById('readiness-content');if(n)n.textContent=e.message;});}else beforeReadiness();if(location.hash==='#program15-curriculum'){const h=document.querySelector('#app');if(h&&!h.querySelector('[href="#readiness-check"]'))h.insertAdjacentHTML('beforeend','<section class="card prose"><a href="#readiness-check">Take the prerequisite self-check</a></section>');}};
document.addEventListener('submit',async e=>{if(e.target.id!=='readiness-form')return;e.preventDefault();const f=new FormData(e.target),n=document.getElementById('readiness-result');try{const d=await readinessCall('score',{goal:f.get('goal'),answers:Array.from({length:10},(_,i)=>Number(f.get('q'+(i+1))))});n.innerHTML=`<h2>${d.score}/${d.total}</h2><p>${esc(d.reason)}</p><p>${d.recommendedPrograms.map(id=>`<a href="#program/${id}">Explore program #${id}</a>`).join(' · ')}</p><p>${esc(d.notice)}</p><ol>${d.feedback.map(a=>`<li>${a.correct?'Correct':'Review'}: ${esc(a.explanation)}</li>`).join('')}</ol>`;}catch(err){n.textContent=err.message;}});render();
